WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget DESC NULLS FIRST, id) AS latest_rank FROM departments) ranked WHERE latest_rank = 1) SELECT id, dept_name, budget, latest_rank, CASE WHEN dept_name RLIKE '^(Finance|Engineering)$' THEN 'GROUP_A' WHEN dept_name RLIKE '^(Sales|Marketing)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS dept_name_zone FROM ranked ORDER BY id, latest_rank
